academyExtension.push(...[{"title":"Riconoscere i tipi di vela","cat":"Vele","level":"Principiante","goal":"Distinguere vele quadre, auriche e triangolari.","gloss":"Vela quadra = sostenuta da pennone trasversale; vela aurica = sostenuta da picco; fiocco = vela triangolare di prua.","tools":"Piano velico, carta, matita, riga.","steps":["Identifica ogni vela per nome e posizione sul piano.","Segna il bordo superiore, inferiore, le cadute e le bugne secondo il tipo di vela.","Decidi la configurazione del modello prima di preparare il cordame: vele spiegate, raccolte oppure assenti."],"check":"Ogni sagoma ha nome, posizione e configurazione documentati.","error":"Usare la stessa sagoma per tutti gli alberi.","practice":"Disegna tre tipi di vela e confronta gli attacchi.","q":"Dove trovi forma e posizione delle vele?","options":["Sul piano velico","Sul colore dello scafo","Nel diametro del timone"],"correct":0,"feedback":"Il piano velico determina la geometria e la posizione.","links":"measure supply","diagram":"types"},{"title":"Scegliere e preparare il tessuto","cat":"Vele","level":"Principiante","goal":"Ottenere una tela sottile e proporzionata.","gloss":"Batista = tela fine; ordito e trama = direzioni dei fili del tessuto.","tools":"Batista di cotone, tela fine o carta silkspan se adatta, forbici, campioni.","steps":["Confronta tessuti sottili e abbastanza opachi contro luce; osserva la trama alla distanza normale.","Per il cotone lavabile, prova lavaggio e stiratura secondo etichetta su uno scarto; misura il ritiro. Per silkspan segui il metodo specifico.","Verifica colore, rigidità e compatibilità di filo e adesivo su campione prima di tagliare."],"check":"Tela stabile, senza pieghe o trama sproporzionata.","error":"Usare tessuto spesso solo perché più facile da cucire.","practice":"Prepara due campioni di tessuto e confrontali sul modello.","q":"Quale tessuto scegli?","options":["Il più spesso","Quello con trama e spessore proporzionati","Qualsiasi tessuto senza prova"],"correct":1,"feedback":"La scala visiva conta più della robustezza del tessuto.","links":"supply tools","diagram":"cloth"},{"title":"Sagome, scala e margini di taglio","cat":"Vele","level":"Principiante","goal":"Trasferire il piano velico alla tela.","gloss":"Margine di cucitura = materiale supplementare per l'orlo; sagoma = contorno finito.","tools":"Piano calibrato, carta, riga, matita fine, forbici.","steps":["Controlla una quota stampata nota e ritaglia una sagoma di carta.","Segna separatamente contorno finito, margine d'orlo e riferimenti di cucitura; il margine dipende dal metodo e dalla scala.","Disponi la sagoma orientando la trama come indicato dal piano, verifica coppie e taglia senza tirare la tela."],"check":"Contorno e orientamento corrispondono alla tavola.","error":"Confondere il contorno finito con la linea di taglio.","practice":"Disegna un rettangolo finito di 60 × 40 mm con margine di prova di 2 mm per lato.","q":"Con margine di 2 mm per lato, quanto misura il taglio nell'esempio?","options":["60 × 40 mm","62 × 42 mm","64 × 44 mm"],"correct":2,"feedback":"Il margine si aggiunge su entrambi i lati di ogni dimensione.","links":"measure tools","diagram":"pattern"},{"title":"Cuciture dei ferzi","cat":"Vele","level":"Intermedio","goal":"Simulare le giunzioni della tela in scala.","gloss":"Ferzo = striscia di tela che compone la vela.","tools":"Filo fine in tinta, ago, macchina da cucire se adatta, righello, campione.","steps":["Ricava direzione e larghezze dei ferzi dal piano; traccia riferimenti leggeri.","Prova punti a mano o a macchina su scarto, con tensione tale da non arricciare. Una linea singola sottile può essere preferibile a una doppia sproporzionata.","Esegui le cuciture prima di rifinire il contorno se il metodo lo richiede; confronta periodicamente le distanze."],"check":"Cuciture dritte e regolari senza arricciamenti.","error":"Usare filo grosso o cuciture marcate fuori scala.","practice":"Cuci tre linee parallele su uno scarto e controlla la planarità.","q":"Cosa fai se la doppia cucitura risulta fuori scala?","options":["Provo una simulazione più fine","Aumento lo spessore del filo","Stringo ancora la tensione"],"correct":0,"feedback":"Il risultato deve rimanere proporzionato alla scala.","links":"supply tools","diagram":"seams"},{"title":"Orli e rinforzi delle vele","cat":"Vele","level":"Intermedio","goal":"Rifinire i bordi e simulare rinforzi documentati.","gloss":"Orlo = bordo ripiegato; rinforzo = zona supplementare di tela.","tools":"Tessuto, filo fine, forbici, dima, adesivo per tessuti se compatibile.","steps":["Segna l'orlo e prova una piega sul campione; controlla lo spessore risultante.","Realizza pieghe sottili o una simulazione appropriata. Aggiungi rinforzi agli angoli o nei punti documentati senza accumulare strati eccessivi.","Rifinisci i bordi controllando il contorno sulla sagoma e verifica che la vela non si deformi."],"check":"Bordo continuo e non troppo spesso.","error":"Incollare rinforzi spessi su ogni angolo senza consultare il piano.","practice":"Prova due tipi di orlo sullo stesso tessuto.","q":"Quale orlo scegli?","options":["Quello più grosso","Quello proporzionato e stabile","Quello con più colla"],"correct":1,"feedback":"Spessore, forma e scala devono rimanere coerenti.","links":"supply tools","diagram":"hem"},{"title":"Gratile e occhielli","cat":"Vele","level":"Intermedio","goal":"Applicare il cordone perimetrale quando previsto.","gloss":"Gratile (bolt rope) = corda cucita al bordo; bugna = angolo di manovra.","tools":"Cordame fine, ago, filo per cuciture, piano delle vele.","steps":["Identifica quali bordi hanno il gratile e quali anelli sono previsti.","Misura il cordame sul campione; fissalo lungo il bordo con punti minuti o tecnica compatibile. Forma gli occhielli documentati senza tirare la tela.","Controlla il perimetro, gli attacchi e le bugne prima di montare la vela."],"check":"Bordi regolari e occhielli proporzionati.","error":"Usare un cordame così grosso da deformare la vela.","practice":"Cuci un breve tratto di gratile su uno scarto.","q":"Quale diametro usi?","options":["Uno uguale per tutte le vele","Il più grosso disponibile","Quello documentato e verificato in scala"],"correct":2,"feedback":"Il gratile è un dettaglio da dimensionare sul progetto.","links":"fittings supply","diagram":"bolt"},{"title":"Terzaroli, matafioni e fasce di rinforzo","cat":"Vele","level":"Intermedio","goal":"Rappresentare i dispositivi per ridurre la superficie velica.","gloss":"Matafioni = brevi legacci; fascia di terzarolo = rinforzo della zona di riduzione.","tools":"Piano velico, filo sottile, ago, righello, campione.","steps":["Individua le file di terzaroli e i rinforzi effettivamente presenti.","Segna le posizioni sulla tela; applica le fasce e i legacci con la tecnica documentata, provando prima su campione.","Regola lunghezza e disposizione dei capi secondo la configurazione scelta; evita nodi eccessivi."],"check":"File ordinate, tessuto non arricciato e legacci proporzionati.","error":"Aggiungere terzaroli a vele che non li prevedono.","practice":"Simula una fila di cinque legacci su un ritaglio.","q":"Come stabilisci il numero di file?","options":["Dal piano e dalla configurazione","Sempre due","Dal numero di pennoni"],"correct":0,"feedback":"Non tutte le vele hanno gli stessi dispositivi di riduzione.","links":"supply measure","diagram":"reef"},{"title":"Tintura e invecchiamento delle vele","cat":"Vele","level":"Intermedio","goal":"Riprodurre una tonalità credibile senza danneggiare il tessuto.","gloss":"Campione = ritaglio usato per verificare il risultato.","tools":"Colorante tessile adatto, recipiente dedicato, guanti secondo etichetta, campioni.","steps":["Scegli una tonalità documentata; confronta tessuto naturale e campioni colorati.","Segui diluizione, lavaggio e fissaggio del colorante specifico. Esegui la tintura prima del montaggio, controllando ritiro e uniformità.","Lascia asciugare e valuta colore e rigidità; applica eventuali effetti leggeri soltanto su campione già stabile."],"check":"Colore uniforme e tessuto non irrigidito.","error":"Bagnare la vela già montata sul modello o usare un mordente per legno non compatibile.","practice":"Confronta un campione naturale con uno colorato completamente asciutto.","q":"Quando valuti la tonalità finale?","options":["Quando il tessuto è ancora bagnato","Dopo asciugatura del campione","Dopo aver montato tutte le vele"],"correct":1,"feedback":"Il tessuto bagnato può apparire molto più scuro.","links":"supply paint","diagram":"dye"},{"title":"Montare le vele quadre sui pennoni","cat":"Vele","level":"Intermedio","goal":"Fissare il bordo superiore e predisporre le manovre.","gloss":"Inferitura = fissaggio del bordo della vela; pennone = asta trasversale.","tools":"Vela finita, pennone preparato, filo fine, pinzette, piano manovre.","steps":["Verifica orientamento, posizione e punti di fissaggio del pennone; prepara i bozzelli che diventeranno inaccessibili.","Fissa il bordo superiore secondo la legatura prevista dal piano; distribuisci i punti senza creare grinze.","Collega le manovre previste per la vela spiegata o raccolta e regola senza deformare pennone e albero."],"check":"Attacchi regolari e pennone nella posizione documentata.","error":"Tendere una scotta fino a incurvare il pennone.","practice":"Appoggia la vela di carta su un pennone di prova e segna gli attacchi.","q":"Prima del fissaggio cosa controlli?","options":["Solo il colore","Solo il peso","Orientamento e accesso ai bozzelli"],"correct":2,"feedback":"La preparazione evita manovre impossibili da raggiungere.","links":"fittings supply","diagram":"square"},{"title":"Montare vele auriche e fiocchi","cat":"Vele","level":"Intermedio","goal":"Distinguere attacchi al picco, boma o straglio.","gloss":"Picco = asta superiore della vela aurica; straglio = sostegno longitudinale.","tools":"Vela finita, attacchi da piano, pinzette, cordame.","steps":["Identifica il bordo di inferitura e gli attacchi specifici: cerchi, legature o altri elementi previsti.","Prova la vela a secco su picco, albero o straglio; installa gli attacchi nella sequenza del piano.","Collega drizze, scotte e altri rinvii prescritti; regola senza deformare il tessuto."],"check":"Vela orientata correttamente e cordame non forzato.","error":"Applicare gli attacchi di una vela quadra a un fiocco.","practice":"Confronta su carta una vela aurica e un fiocco e indica gli attacchi.","q":"Dove trovi i sistemi di fissaggio?","options":["Sul piano velico e delle manovre","In una regola uguale per ogni vela","Nella tabella dei mordenti"],"correct":0,"feedback":"Ogni tipo di vela ha attacchi propri.","links":"fittings supply","diagram":"foreaft"},{"title":"Vele raccolte e modelli senza vele","cat":"Vele","level":"Avanzato","goal":"Scegliere una configurazione coerente per l'intero modello.","gloss":"Vela serrata = vela raccolta sul pennone o asta; matafioni di serraggio = legacci specifici.","tools":"Piano manovre, tessuto sottile o materiale alternativo, filo fine.","steps":["Scegli una configurazione documentata prima di completare le manovre.","Per vele raccolte prova su scarto una sagoma ridotta o tessuto più sottile per evitare un volume fuori scala. Distribuisci pieghe e legature secondo il progetto.","Se ometti le vele, controlla quali manovre restano e come terminano secondo il manuale; non lasciare capi liberi arbitrari."],"check":"Volume credibile e configurazione coerente delle manovre.","error":"Arrotolare una vela intera spessa senza verificare il volume.","practice":"Confronta due piccoli campioni raccolti con spessori diversi.","q":"Cosa determina le manovre da mantenere?","options":["Il numero di colori","La configurazione scelta e il manuale","Il tipo di colla"],"correct":1,"feedback":"Le manovre dipendono anche dalla presenza delle vele.","links":"supply fittings","diagram":"furled"},{"title":"Commettitrice: produrre e misurare il cordame","cat":"Alberatura","level":"Avanzato","goal":"Realizzare una corda uniforme e ripetibile.","gloss":"Trefolo = gruppo di fili ritorti; commettitura = unione dei trefoli.","tools":"Commettitrice modellistica, filo regolare, calibro, supporti e istruzioni della macchina.","steps":["Scegli materiale e costruzione da documentazione; usa una prova corta. Predisponi i trefoli con lunghezza e tensione uniformi secondo manuale.","Torci e accompagna la commettitura nel verso previsto dalla macchina, evitando nodi e contatto con parti rotanti. Ferma la macchina prima di regolare.","Lascia stabilizzare e misura il diametro in più punti senza comprimere. Registra filo, trefoli, lunghezza iniziale e finale e diametro; ripeti se necessario."],"check":"Cordame regolare e stabile con diametro verificato.","error":"Calcolare il diametro sommando semplicemente quello dei singoli fili.","practice":"Crea una tabella di prova per due campioni, registrando i risultati effettivi.","q":"Come conosci il diametro finale?","options":["Sommando i diametri dei fili","Usando sempre lo stesso diametro","Misurando la corda finita"],"correct":2,"feedback":"Torsione, tensione e struttura cambiano il diametro finale.","links":"tools supply","diagram":"ropewalk"}]);
