function chapterProgress(ids){
 const done=ids.filter(i=>state.done.includes(i-1)).length;
 const read=ids.filter(i=>!state.done.includes(i-1)&&studyReadList().includes(i-1)).length;
 return {done,read,seen:done+read,total:ids.length};
}
